package net.officefloor.hq.app.claim;

/** A status change the claim's current status (or who opened it) does not allow. */
public class ClaimStatusNotAllowedException extends Exception {
    public ClaimStatusNotAllowedException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to + ".");
    }

    public ClaimStatusNotAllowedException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimStatusNotAllowed {
    public void handle(@Parameter ClaimStatusNotAllowedException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.claim.Claim;
import net.officefloor.plugin.variable.Val;

/** Refuse opening, settling, voiding, moving, deferring, splitting or adding a proof to a claim whose due-by falls inside a closed period. */
public class RefuseClosedClaim {
    public void refuse(@Val Claim loaded, PeriodRepository periods) throws ClosedPeriodException {
        periods.lockSheet(loaded.sheetId());
        Period closed = periods.closedOn(loaded.sheetId(), loaded.dueBy());
        if (closed != null) {
            throw new ClosedPeriodException(closed);
        }
    }
}
